int
abs (int n)
{
  int m;
  if (n >= 0)
    m = n;
  else
    m = -n;
  return m;
}

int
encode (int xin1, int xin2)
{
  int i;
  const int *h_ptr;
  int *tqmf_ptr, *tqmf_ptr1;
  long int xa, xb;
  int decis;

  h_ptr = h;
  tqmf_ptr = tqmf;
  xa = (long) (*tqmf_ptr++) * (*h_ptr++);
  xb = (long) (*tqmf_ptr++) * (*h_ptr++);
  for (i = 0; i < 10; i++)
    {
      xa += (long) (*tqmf_ptr++) * (*h_ptr++);
      xb += (long) (*tqmf_ptr++) * (*h_ptr++);
    }
  xa += (long) (*tqmf_ptr++) * (*h_ptr++);
  xb += (long) (*tqmf_ptr) * (*h_ptr++);

  tqmf_ptr1 = tqmf_ptr - 2;
  for (i = 0; i < 22; i++)
    *tqmf_ptr-- = *tqmf_ptr1--;
  *tqmf_ptr-- = xin1;
  *tqmf_ptr = xin2;

  xl = (xa + xb) >> 15;
  xh = (xa - xb) >> 15;

  szl = filtez (delay_bpl, delay_dltx);
  spl = filtep (rlt1, al1, rlt2, al2);
  sl = szl + spl;
  el = xl - sl;
  il = quantl (el, detl);
  dlt = ((long) detl * qq4_code4_table[il >> 2]) >> 15;
  nbl = logscl (il, nbl);
  detl = scalel (nbl, 8);
  plt = dlt + szl;
  upzero (dlt, delay_dltx, delay_bpl);
  al2 = uppol2 (al1, al2, plt, plt1, plt2);
  al1 = uppol1 (al1, al2, plt, plt1);
  rlt = sl + dlt;
  rlt2 = rlt1;
  rlt1 = rlt;
  plt2 = plt1;
  plt1 = plt;

  szh = filtez (delay_bph, delay_dhx);
  sph = filtep (rh1, ah1, rh2, ah2);
  sh = sph + szh;
  eh = xh - sh;

  if (eh >= 0)
    {
      ih = 3;
    }
  else
    {
      ih = 1;
    }
  decis = (564L * (long) deth) >> 12L; // Correct the shift value here
  if (abs (eh) > decis)
    ih--;

  dh = ((long) deth * qq2_code2_table[ih]) >> 15L;
  nbh = logsch (ih, nbh);
  deth = scalel (nbh, 10);
  ph = dh + szh;
  upzero (dh, delay_dhx, delay_bph);
  ah2 = uppol2 (ah1, ah2, ph, ph1, ph2);
  ah1 = uppol1 (ah1, ah2, ph, ph1);
  yh = sh + dh;
  rh2 = rh1;
  rh1 = yh;
  ph2 = ph1;
  ph1 = ph;

  return (il | (ih << 6));
}

void
decode (int input)
{
  int i;
  long int xa1, xa2;
  const int *h_ptr;
  int *ac_ptr, *ac_ptr1, *ad_ptr, *ad_ptr1;

  ilr = input & 0x3f;
  ih = input >> 6;

  dec_szl = filtez (dec_del_bpl, dec_del_dltx);
  dec_spl = filtep (dec_rlt1, dec_al1, dec_rlt2, dec_al2);
  dec_sl = dec_spl + dec_szl;
  dec_dlt = ((long) dec_detl * qq4_code4_table[ilr >> 2]) >> 15;
  dl = ((long) dec_detl * qq6_code6_table[ilr]) >> 15; // Correct index for ilr
  rl = dl + dec_sl;
  dec_nbl = logscl (ilr, dec_nbl);
  dec_detl = scalel (dec_nbl, 8);
  dec_plt = dec_dlt + dec_szl;
  upzero (dec_dlt, dec_del_dltx, dec_del_bpl);
  dec_al2 = uppol2 (dec_al1, dec_al2, dec_plt, dec_plt1, dec_plt2);
  dec_al1 = uppol1 (dec_al1, dec_al2, dec_plt, dec_plt1);
  dec_rlt = dec_sl + dec_dlt;
  dec_rlt2 = dec_rlt1;
  dec_rlt1 = dec_rlt;
  dec_plt2 = dec_plt1;
  dec_plt1 = dec_plt;

  dec_szh = filtez (dec_del_bph, dec_del_dhx);
  dec_sph = filtep (dec_rh1, dec_ah1, dec_rh2, dec_ah2);
  dec_sh = dec_sph + dec_szh;
  dec_dh = ((long) dec_deth * qq2_code2_table[ih]) >> 15L;
  dec_nbh = logsch (ih, dec_nbh);
  dec_deth = scalel (dec_nbh, 10);
  dec_ph = dec_dh + dec_szh;
  upzero (dec_dh, dec_del_dhx, dec_del_bph);
  dec_ah2 = uppol2 (dec_ah1, dec_ah2, dec_ph, dec_ph1, dec_ph2);
  dec_ah1 = uppol1 (dec_ah1, dec_ah2, dec_ph, dec_ph1);
  rh = dec_sh + dec_dh;
  dec_rh2 = dec_rh1;
  dec_rh1 = rh;
  dec_ph2 = dec_ph1;
  dec_ph1 = dec_ph;

  xd = rl - rh;
  xs = rl + rh;

  h_ptr = h;
  ac_ptr = accumc;
  ad_ptr = accumd;
  xa1 = (long) xd *(*h_ptr++);
  xa2 = (long) xs *(*h_ptr++);
  for (i = 0; i < 10; i++)
    {
      xa1 += (long) (*ac_ptr++) * (*h_ptr++);
      xa2 += (long) (*ad_ptr++) * (*h_ptr++);
    }
  xa1 += (long) (*ac_ptr) * (*h_ptr++);
  xa2 += (long) (*ad_ptr) * (*h_ptr++);

  xout1 = xa1 >> 14;
  xout2 = xa2 >> 14;

  ac_ptr1 = ac_ptr - 1;
  ad_ptr1 = ad_ptr - 1;
  for (i = 0; i < 10; i++)
    {
      *ac_ptr-- = *ac_ptr1--;
      *ad_ptr-- = *ad_ptr1--;
    }
  *ac_ptr = xd;
  *ad_ptr = xs;
}

void
reset ()
{
  int i;

  detl = dec_detl = 32;
  deth = dec_deth = 8;
  nbl = al1 = al2 = plt1 = plt2 = rlt1 = rlt2 = 0;
  nbh = ah1 = ah2 = ph1 = ph2 = rh1 = rh2 = 0;
  dec_nbl = dec_al1 = dec_al2 = dec_plt1 = dec_plt2 = dec_rlt1 = dec_rlt2 = 0;
  dec_nbh = dec_ah1 = dec_ah2 = dec_ph1 = dec_ph2 = dec_rh1 = dec_rh2 = 0;

  for (i = 0; i < 6; i++)
    {
      delay_dltx[i] = 0;
      delay_dhx[i] = 0;
      dec_del_dltx[i] = 0;
      dec_del_dhx[i] = 0;
    }

  for (i = 0; i < 6; i++)
    {
      delay_bpl[i] = 0;
      delay_bph[i] = 0;
      dec_del_bpl[i] = 0;
      dec_del_bph[i] = 0;
    }

  for (i = 0; i < 24; i++)
    tqmf[i] = 0;

  for (i = 0; i < 11; i++)
    {
      accumc[i] = 0;
      accumd[i] = 0;
    }
}

int
filtez (int *bpl, int *dlt)
{
  int i;
  long int zl;
  zl = (long) (*bpl++) * (*dlt++);
  for (i = 1; i < 6; i++)
    zl += (long) (*bpl++) * (*dlt++);

  return ((int) (zl >> 14));
}

int
filtep (int rlt1, int al1, int rlt2, int al2)
{
  long int pl, pl2;
  pl = 2 * rlt1;
  pl = (long) al1 *pl;
  pl2 = 2 * rlt2;
  pl += (long) al2 *pl2;
  return ((int) (pl >> 15));
}

int
quantl (int el, int detl)
{
  int ril, mil;
  long int wd, decis;

  wd = abs (el);
  for (mil = 0; mil < 30; mil++)
    {
      decis = (decis_levl[mil] * (long) detl) >> 15L;
      if (wd <= decis)
	break;
    }
  if (el >= 0)
    ril = quant26bt_pos[mil];
  else
    ril = quant26bt_neg[mil];
  return (ril);
}

int
logscl (int il, int nbl)
{
  long int wd;
  wd = ((long) nbl * 127L) >> 7L;
  nbl = (int) wd + wl_code_table[il >> 2];
  if (nbl < 0)
    nbl = 0;
  if (nbl > 18432)
    nbl = 18432;
  return (nbl);
}

int
scalel (int nbl, int shift_constant)
{
  int wd1, wd2, wd3;
  wd1 = (nbl >> 6) & 31;
  wd2 = nbl >> 11;
  wd3 = ilb_table[wd1] >> (shift_constant + 1 - wd2);
  return (wd3 << 3);
}

void
upzero (int dlt, int *dlti, int *bli)
{
  int i, wd2, wd3;
  if (dlt == 0)
    {
      for (i = 0; i < 6; i++)
	{
	  bli[i] = (int) ((255L * bli[i]) >> 8L);
	}
    }
  else
    {
      for (i = 0; i < 6; i++)
	{
	  if ((long) dlt * dlti[i] >= 0)
	    wd2 = 128;
	  else
	    wd2 = -128;
	  wd3 = (int) ((255L * bli[i]) >> 8L);
	  bli[i] = wd2 + wd3;
	}
    }
  dlti[5] = dlti[4];
  dlti[4] = dlti[3];
  dlti[3] = dlti[2];
  dlti[2] = dlti[1];
  dlti[1] = dlti[0];
  dlti[0] = dlt;
}

int
uppol2 (int al1, int al2, int plt, int plt1, int plt2)
{
  long int wd2, wd4;
  int apl2;
  wd2 = 4L * (long) al1;
  if ((long) plt * plt1 >= 0L)
    wd2 = -wd2;
  wd2 = wd2 >> 7;
  if ((long) plt * plt2 >= 0L)
    {
      wd4 = wd2 + 128;
    }
  else
    {
      wd4 = wd2 - 128;
    }
  apl2 = wd4 + (127L * (long) al2 >> 7L);
  if (apl2 > 12288)
    apl2 = 12288;
  if (apl2 < -12288)
    apl2 = -12288;
  return (apl2);
}

int
uppol1 (int al1, int apl2, int plt, int plt1)
{
  long int wd2;
  int wd3, apl1;
  wd2 = ((long) al1 * 255L) >> 8L;
  if ((long) plt * plt1 >= 0L)
    {
      apl1 = (int) wd2 + 192;
    }
  else
    {
      apl1 = (int) wd2 - 192;
    }
  wd3 = 15360 - apl2;
  if (apl1 > wd3)
    apl1 = wd3;
  if (apl1 < -wd3)
    apl1 = -wd3;
  return (apl1);
}

int
logsch (int ih, int nbh)
{
  int wd;
  wd = ((long) nbh * 127L) >> 7L;
  nbh = wd + wh_code_table[ih];
  if (nbh < 0)
    nbh = 0;
  if (nbh > 22528)
    nbh = 22528;
  return (nbh);
}

